import { readFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { gunzipSync, brotliDecompressSync } from 'node:zlib';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const fingerprintVersion = 2;
export const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');

// Cache paths and UIDs are regenerated by import; importer options change the export.
export function importSettings(text) {
  let section = '';
  return text.split(/\r?\n/).filter(line => {
    const trimmed = line.trim();
    if (/^\[.*\]$/.test(trimmed)) section = trimmed;
    return section === '[params]' || (section === '[remap]' && /^(importer|importer_version|type)=/.test(trimmed));
  }).join('\n').trim();
}

async function filesUnder(root, relative) {
  const files = [];
  const entries = await readdir(join(root, relative), { withFileTypes: true });
  entries.sort((a, b) => a.name.localeCompare(b.name, 'en'));
  for (const entry of entries) {
    if (entry.name.startsWith('.') || (relative === 'game' && entry.name === 'tests')) continue;
    const path = `${relative}/${entry.name}`;
    if (entry.isDirectory()) files.push(...await filesUnder(root, path));
    else if (entry.isFile()) files.push(path);
  }
  return files;
}

export async function sourceFingerprint(root = projectRoot) {
  const sources = {};
  for (const path of await filesUnder(root, 'game')) {
    if (path.endsWith('.uid')) continue;
    const bytes = await readFile(join(root, path));
    sources[path] = sha256(path.endsWith('.import') ? importSettings(bytes.toString('utf8')) : bytes);
  }
  return { schemaVersion: fingerprintVersion, sources, sourceHash: sha256(JSON.stringify(sources)) };
}

export async function verifyEngine(directory, manifestName = 'engine-export-manifest.json', root = projectRoot) {
  const manifest = JSON.parse(await readFile(join(directory, manifestName), 'utf8'));
  if (manifest.schemaVersion !== fingerprintVersion || manifest.engineVersion !== '4.7.2') {
    throw new Error('Export manifest must be regenerated with npm run build:engine.');
  }
  const fingerprint = await sourceFingerprint(root);
  const changed = [...new Set([...Object.keys(fingerprint.sources), ...Object.keys(manifest.sources || {})])]
    .filter(path => fingerprint.sources[path] !== manifest.sources?.[path]);
  if (changed.length || fingerprint.sourceHash !== manifest.sourceHash) {
    throw new Error(`Godot export is stale: ${changed.slice(0, 5).join(', ') || 'source fingerprint'}. Run npm run build:engine.`);
  }
  for (const name of ['engine.js', 'engine.wasm', 'engine.pck']) {
    if (!manifest.files?.[name]) throw new Error(`Export manifest is missing ${name}`);
  }
  for (const [name, hash] of Object.entries(manifest.files)) {
    if (!/^engine\.[a-z0-9.]+$/i.test(name) || sha256(await readFile(join(directory, name))) !== hash) {
      throw new Error(`Invalid Godot runtime file: ${name}`);
    }
  }
  return manifest;
}

export async function verifyPackage(directory, root = projectRoot) {
  const manifest = await verifyEngine(directory, 'engine-export-manifest.json', root);
  const files = [...await filesUnder(root, 'web'), ...await filesUnder(root, 'licenses'), 'asset-manifest.json'];
  for (const path of files) {
    const relative = path.startsWith('web/') ? path.slice(4) : path;
    if (sha256(await readFile(join(directory, relative))) !== sha256(await readFile(join(root, path)))) {
      throw new Error(`Web package is stale: ${relative}. Run npm run build.`);
    }
  }
  for (const path of await filesUnder(directory, '.')) {
    const extension = path.endsWith('.gz') ? '.gz' : path.endsWith('.br') ? '.br' : null;
    if (!extension) continue;
    const compressed = await readFile(join(directory, path));
    const original = await readFile(join(directory, path.slice(0, -extension.length)));
    const decoded = extension === '.br' ? brotliDecompressSync(compressed) : gunzipSync(compressed);
    if (sha256(decoded) !== sha256(original)) throw new Error(`Stale ${extension === '.br' ? 'Brotli' : 'gzip'} sidecar: ${path}`);
  }
  return manifest;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const fingerprint = process.argv[2] === '--verify-package'
      ? await verifyPackage(resolve(process.argv[3] || 'dist'))
      : await sourceFingerprint();
    console.log(JSON.stringify(fingerprint));
  } catch (error) { console.error(error.message); process.exitCode = 1; }
}
